// Macro to roll the Sites Crucible tables

const rolltable1Name = "Sites Crucible - Adjective";
const rolltable2Name = "Sites Crucible - Noun";

// Function to roll a table by name
async function rollTable(tableName) {
  const table = game.tables.getName(tableName);
  if (!table) {
    ui.notifications.error(`RollTable "${tableName}" not found.`);
    return;
  }

  const rollResult = await table.roll();
  const resultText = rollResult.results
    .map((r) => r.text)
    .join(", ");

  return resultText;
}

// Roll both tables
const result1 = await rollTable(rolltable1Name);
const result2 = await rollTable(rolltable2Name);

if (result1 && result2) {
  ChatMessage.create({
    content: `<b>Sites Crucible</b><br><i>Smash them together and interpret</i><br>
    <b>${result1}</b><br><b>${result2}</b>`
  });
}
